const BOT_TOKEN = '8791438411:AAFKzCvX3g4xh3IW6V5jqzoc7SxDOqR_Pns';
const BASE_URL = `https://api.telegram.org/bot${BOT_TOKEN}`;

const chatId = $('Parse & Send Direct Reply').item.json.chatId;
const messageThreadId = $('Parse & Send Direct Reply').item.json.messageThreadId;
let aiOutput = ($input.item.json.output || '').trim();

// Bersihkan kurung siku < > pada URL agar tidak merusak parser HTML Telegram
aiOutput = aiOutput.replace(/<(https?:\/\/[^>]+)>/g, '$1');

// Konversi markdown **bold** & *italic* jika AI masih tidak sengaja memakainya
aiOutput = aiOutput.replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');
aiOutput = aiOutput.replace(/\*(.*?)\*/g, '<i>$1</i>');

const imageUrlMatch = aiOutput.match(/https:\/\/tikael\.kereaktif\.id\/[^\s\)"]+\.(jpg|jpeg|png)/i);

async function sendMsg(bodyObj) {
  if (messageThreadId) bodyObj.message_thread_id = messageThreadId;
  return await this.helpers.httpRequest({
    method: 'POST',
    url: `${BASE_URL}/sendMessage`,
    body: bodyObj,
    json: true
  });
}

async function sendPic(bodyObj) {
  if (messageThreadId) bodyObj.message_thread_id = messageThreadId;
  return await this.helpers.httpRequest({
    method: 'POST',
    url: `${BASE_URL}/sendPhoto`,
    body: bodyObj,
    json: true
  });
}

if (imageUrlMatch) {
  const imageUrl = imageUrlMatch[0];
  // Strip raw photo URL from caption text so customers don't see tikael.kereaktif.id domain link!
  let cleanCaption = aiOutput.replace(imageUrl, '').replace(/<https?:[^>]+>/g, '').trim();
  const caption = cleanCaption.length > 0 && cleanCaption.length <= 1024 ? cleanCaption : undefined;
  try {
    await sendPic.call(this, { chat_id: chatId, photo: imageUrl, caption, parse_mode: 'HTML' });
  } catch (e) {
    await sendPic.call(this, { chat_id: chatId, photo: imageUrl, caption });
  }
  if (cleanCaption.length > 1024) {
    try {
      await sendMsg.call(this, { chat_id: chatId, text: cleanCaption, parse_mode: 'HTML' });
    } catch (e) {
      await sendMsg.call(this, { chat_id: chatId, text: cleanCaption });
    }
  }
} else {
  try {
    await sendMsg.call(this, { chat_id: chatId, text: aiOutput, parse_mode: 'HTML' });
  } catch (e) {
    await sendMsg.call(this, { chat_id: chatId, text: aiOutput });
  }
}

return { done: true };
